                    hi = mid - 1;
                } else {
                    lo = mid + 1;
                }
            } else {                                            // 右半有序
                if (nums[mid] < target && target <= nums[hi]) {
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
        }
        return -1;
    }
}

